## 2. Elixir Router

**lib/alphafold_router/router.ex**

```elixir
defmodule AlphaFoldRouter.Router do
  use Plug.Router

  plug Plug.Logger
  plug :match
  plug Plug.Parsers,
    parsers: [:json],
    pass: ["application/json"],
    json_decoder: Jason
  plug :dispatch

  post "/api/predict" do
    sequence = conn.body_params["sequence"]

    backend = select_optimal_backend()

    case route_to_backend(backend, sequence) do
      {:ok, result} ->
        conn
        |> put_resp_content_type("application/json")
        |> send_resp(200, Jason.encode!(result))

      {:error, reason} ->
        conn
        |> put_resp_content_type("application/json")
        |> send_resp(500, Jason.encode!(%{error: reason}))
    end
  end

  match _ do
    send_resp(conn, 404, "Not Found")
  end

  defp select_optimal_backend do
    backends = [
      {:julia_service, "julia_worker"},
      {:futhark_service, "futhark_gpu"},
      {:chapel_service, "chapel_cluster"}
    ]

    backend_loads = Enum.map(backends, fn {name, worker} ->
      load = :erlang.send(String.to_atom(worker), {:get_load, self()})
      receive do
        {:load, value} -> {name, value}
      after
        100 -> {name, 1.0}
      end
    end)

    {backend, _load} = Enum.min_by(backend_loads, fn {_name, load} -> load end)
    backend
  end

  defp route_to_backend(:julia_service, sequence) do
    port = Port.open({:spawn, "julia main.jl #{sequence}"}, [:binary, :exit_status])
    receive_result(port)
  end

  defp route_to_backend(:futhark_service, sequence) do
    port = Port.open({:spawn, "./futhark_inference #{sequence}"}, [:binary, :exit_status])
    receive_result(port)
  end

  defp route_to_backend(:chapel_service, sequence) do
    port = Port.open({:spawn, "./chapel_msa #{sequence}"}, [:binary, :exit_status])
    receive_result(port)
  end

  defp receive_result(port) do
    receive do
      {^port, {:data, data}} ->
        {:ok, Jason.decode!(data)}
      {^port, {:exit_status, 0}} ->
        {:ok, %{status: "complete"}}
      {^port, {:exit_status, status}} ->
        {:error, "Process exited with status #{status}"}
    after
      300_000 ->
        {:error, "Timeout"}
    end
  end
end

defmodule AlphaFoldRouter.Application do
  use Application

  def start(_type, _args) do
    children = [
      {Plug.Cowboy, scheme: :http, plug: AlphaFoldRouter.Router, options: [port: 4000]},
      {AlphaFoldRouter.LoadBalancer, []}
    ]

    opts = [strategy: :one_for_one, name: AlphaFoldRouter.Supervisor]
    Supervisor.start_link(children, opts)
  end
end

defmodule AlphaFoldRouter.LoadBalancer do
  use GenServer

  def start_link(_opts) do
    GenServer.start_link(__MODULE__, %{}, name: __MODULE__)
  end

  def init(state) do
    schedule_health_check()
    {:ok, Map.merge(state, %{backends: init_backends()})}
  end

  def handle_info(:health_check, state) do
    updated_backends = Enum.map(state.backends, fn backend ->
      check_backend_health(backend)
    end)

    schedule_health_check()
    {:noreply, %{state | backends: updated_backends}}
  end

  defp init_backends do
    [
      %{name: :julia_service, host: "localhost", port: 5001, healthy: true},
      %{name: :futhark_service, host: "localhost", port: 5002, healthy: true},
      %{name: :chapel_service, host: "localhost", port: 5003, healthy: true}
    ]
  end

  defp check_backend_health(backend) do
    case :httpc.request(:head, {'', []}, [{:timeout, 1000}], []) do
      {:ok, {{_, 200, _}, _, _}} ->
        %{backend | healthy: true}
      _ ->
        %{backend | healthy: false}
    end
  end

  defp schedule_health_check do
    Process.send_after(self(), :health_check, 5000)
  end
end
