## 3. Erlang Connection Pool

**beam_pool_manager.erl**

```erlang
-module(beam_pool_manager).
-behaviour(gen_server).

-export([start_link/0, checkout/1, checkin/2, get_stats/0]).
-export([init/1, handle_call/3, handle_cast/2, handle_info/2, terminate/2, code_change/3]).

-record(state, {
    pools = #{},
    stats = #{}
}).

-record(pool, {
    language,
    workers = [],
    available = [],
    in_use = []
}).

start_link() ->
    gen_server:start_link({local, ?MODULE}, ?MODULE, [], []).

checkout(Language) ->
    gen_server:call(?MODULE, {checkout, Language}, 30000).

checkin(Language, Worker) ->
    gen_server:cast(?MODULE, {checkin, Language, Worker}).

get_stats() ->
    gen_server:call(?MODULE, get_stats).

init([]) ->
    process_flag(trap_exit, true),
    Pools = init_pools(),
    {ok, #state{pools = Pools, stats = #{}}}.

init_pools() ->
    Languages = [julia, futhark, chapel, jax, mlx, qsharp, gleam, nim],
    lists:foldl(fun(Lang, Acc) ->
        Workers = start_workers(Lang, 8),
        Pool = #pool{
            language = Lang,
            workers = Workers,
            available = Workers,
            in_use = []
        },
        maps:put(Lang, Pool, Acc)
    end, #{}, Languages).

start_workers(Language, Count) ->
    [spawn_link(fun() -> worker_loop(Language) end) || _ <- lists:seq(1, Count)].

worker_loop(Language) ->
    receive
        {execute, Task, From} ->
            Result = execute_task(Language, Task),
            From ! {result, Result},
            worker_loop(Language);
        stop ->
            ok
    end.

execute_task(julia, Task) ->
    Port = open_port({spawn, "julia -e 'println(42)'"}, [binary, exit_status]),
    receive_port_data(Port);
execute_task(futhark, Task) ->
    Port = open_port({spawn, "./futhark_kernel"}, [binary, exit_status]),
    receive_port_data(Port);
execute_task(chapel, Task) ->
    Port = open_port({spawn, "./chapel_msa"}, [binary, exit_status]),
    receive_port_data(Port);
execute_task(_, _) ->
    {ok, <<"executed">>}.

receive_port_data(Port) ->
    receive
        {Port, {data, Data}} ->
            {ok, Data};
        {Port, {exit_status, 0}} ->
            {ok, <<"complete">>};
        {Port, {exit_status, Status}} ->
            {error, Status}
    after 60000 ->
        {error, timeout}
    end.

handle_call({checkout, Language}, From, State) ->
    Pool = maps:get(Language, State#state.pools),
    case Pool#pool.available of
        [Worker | Rest] ->
            UpdatedPool = Pool#pool{
                available = Rest,
                in_use = [Worker | Pool#pool.in_use]
            },
            UpdatedPools = maps:put(Language, UpdatedPool, State#state.pools),
            {reply, {ok, Worker}, State#state{pools = UpdatedPools}};
        [] ->
            {reply, {error, no_workers_available}, State}
    end;

handle_call(get_stats, _From, State) ->
    Stats = maps:map(fun(_Lang, Pool) ->
        #{
            total => length(Pool#pool.workers),
            available => length(Pool#pool.available),
            in_use => length(Pool#pool.in_use)
        }
    end, State#state.pools),
    {reply, {ok, Stats}, State}.

handle_cast({checkin, Language, Worker}, State) ->
    Pool = maps:get(Language, State#state.pools),
    UpdatedPool = Pool#pool{
        available = [Worker | Pool#pool.available],
        in_use = lists:delete(Worker, Pool#pool.in_use)
    },
    UpdatedPools = maps:put(Language, UpdatedPool, State#state.pools),
    {noreply, State#state{pools = UpdatedPools}};

handle_cast(_Msg, State) ->
    {noreply, State}.

handle_info({'EXIT', Pid, Reason}, State) ->
    io:format("Worker ~p exited with reason ~p~n", [Pid, Reason]),
    {noreply, State};

handle_info(_Info, State) ->
    {noreply, State}.

terminate(_Reason, State) ->
    maps:foreach(fun(_Lang, Pool) ->
        [Worker ! stop || Worker <- Pool#pool.workers]
    end, State#state.pools),
    ok.

code_change(_OldVsn, State, _Extra) ->
    {ok, State}.
```

