## 4. Futhark GPU Tensor Kernel

**futhark_attention.fut**

```futhark
let dot_product [n] (a: [n]f32) (b: [n]f32): f32 =
  reduce (+) 0.0f32 (map2 (*) a b)

let softmax [n] (scores: [n]f32): [n]f32 =
  let max_score = reduce f32.max (-f32.inf) scores
  let exp_scores = map (\s -> f32.exp(s - max_score)) scores
  let sum_exp = reduce (+) 0.0f32 exp_scores
  in map (\e -> e / sum_exp) exp_scores

let weighted_sum [n][d] (weights: [n]f32) (values: [n][d]f32): [d]f32 =
  let scaled = map2 (\w v -> map (*w) v) weights values
  in reduce (map2 (+)) (replicate d 0.0f32) scaled

let multi_head_attention [n][m][d] 
    (queries: [n][m][d]f32)
    (keys: [n][m][d]f32)
    (values: [n][m][d]f32): [n][m][d]f32 =
  map (\query_batch ->
    map (\q ->
      let scores = map (dot_product q) query_batch
      let weights = softmax scores
      in weighted_sum weights query_batch
    ) query_batch
  ) queries

let evoformer_block [n][m][d] 
    (msa: [n][m][d]f32)
    (pair: [n][n][d]f32): ([n][m][d]f32, [n][n][d]f32) =
  let msa_attended = multi_head_attention msa msa msa
  let msa_updated = map2 (map2 (map2 (+))) msa msa_attended
  let pair_sum = map (\row -> 
    map (\col -> 
      reduce (+) 0.0f32 (map (\i -> pair[i,col,0]) (iota n))
    ) (iota n)
  ) (iota n)
  let pair_updated = map2 (map2 (\p s -> 
    map (\x -> x + s) p
  )) pair (map (replicate n) pair_sum)
  in (msa_updated, pair_updated)

let evoformer_stack [n][m][d] (num_layers: i64)
    (msa_init: [n][m][d]f32)
    (pair_init: [n][n][d]f32): ([n][m][d]f32, [n][n][d]f32) =
  loop (msa, pair) = (msa_init, pair_init) for i < num_layers do
    evoformer_block msa pair

entry main [n][m][d] 
    (msa: [n][m][d]f32) 
    (pair: [n][n][d]f32) 
    (num_layers: i64): ([n][m][d]f32, [n][n][d]f32) =
  evoformer_stack num_layers msa pair
```

