## 5. Chapel Distributed MSA

**chapel_msa.chpl**

```chapel
use BlockDist;
use Time;
use IO;
use List;

config const numNodes = 128;
config const sequenceLength = 512;
config const databaseSize = 1000000;

record MSAHit {
  var sequence: string;
  var score: real;
  var evalue: real;
}

proc distributedBlastSearch(query: string, numLocales: int): list(MSAHit) {
  const Space = {0..#databaseSize};
  const D = Space dmapped new blockDist(Space);
  var hits: list(MSAHit);

  forall idx in D with (ref hits) {
    const dbSeq = generateDatabaseSequence(idx);
    const alignScore = smithWaterman(query, dbSeq);

    if alignScore > 50.0 {
      const evalue = calculateEvalue(alignScore, query.size, dbSeq.size);
      const hit = new MSAHit(dbSeq, alignScore, evalue);
      hits.pushBack(hit);
    }
  }

  return hits;
}

proc generateDatabaseSequence(idx: int): string {
  const aminoAcids = "ACDEFGHIKLMNPQRSTVWY";
  var seq: string;
  var rng = new randomStream(uint, idx);

  for i in 0..#sequenceLength {
    const aaIdx = (rng.next() % 20): int;
    seq += aminoAcids[aaIdx];
  }

  return seq;
}

proc smithWaterman(seq1: string, seq2: string): real {
  const m = seq1.size;
  const n = seq2.size;
  var H: [0..m, 0..n] real;

  const match = 2.0;
  const mismatch = -1.0;
  const gap = -1.0;

  var maxScore = 0.0;

  for i in 1..m {
    for j in 1..n {
      const diagonal = H[i-1, j-1] + (if seq1[i-1] == seq2[j-1] then match else mismatch);
      const up = H[i-1, j] + gap;
      const left = H[i, j-1] + gap;

      H[i, j] = max(0.0, diagonal, up, left);
      maxScore = max(maxScore, H[i, j]);
    }
  }

  return maxScore;
}

proc calculateEvalue(score: real, m: int, n: int): real {
  const K = 0.13;
  const lambda = 0.318;
  return K * m * n * exp(-lambda * score);
}

proc main() {
  var timer: stopwatch;
  timer.start();

  const query = "MEEPQSDPSVEPPLSQETFSDLWKLLPENNVLSPLPSQAMDDLMLSPDDIEQWFTEDPGPDEAPRMPEAAPPVAPAPAAPTPAAPAPAPSWPLSSSVPSQKTYQGSYGFRLGFLHS";

  writeln("Starting distributed MSA search across ", numLocales, " locales");
  writeln("Query length: ", query.size);
  writeln("Database size: ", databaseSize);

  const results = distributedBlastSearch(query, numLocales);

  timer.stop();

  writeln("Search complete!");
  writeln("Total hits found: ", results.size);
  writeln("Elapsed time: ", timer.elapsed(), " seconds");
  writeln("Throughput: ", databaseSize / timer.elapsed(), " sequences/second");

  writeln("\nTop 10 hits:");
  for i in 0..#min(10, results.size) {
    const hit = results[i];
    writeln("  Score: ", hit.score, " E-value: ", hit.evalue);
  }
}
```

