## 6. ArrayFire FFT

**arrayfire_fft.cpp**

```cpp
#include <arrayfire.h>
#include <cstdio>
#include <cmath>
#include <vector>

using namespace af;

array load_density_map(const char* filename, int nx, int ny, int nz) {
    std::vector<float> data(nx * ny * nz);
    FILE* fp = fopen(filename, "rb");
    if (fp) {
        fread(data.data(), sizeof(float), data.size(), fp);
        fclose(fp);
    }
    return array(nx, ny, nz, data.data());
}

array apply_filter(const array& fft_result, float cutoff_freq) {
    int nx = fft_result.dims(0);
    int ny = fft_result.dims(1);
    int nz = fft_result.dims(2);

    array kx = tile(seq(0, nx-1), 1, ny, nz);
    array ky = tile(moddims(seq(0, ny-1), 1, ny), nx, 1, nz);
    array kz = tile(moddims(seq(0, nz-1), 1, 1, nz), nx, ny);

    kx = (kx > nx/2) * (kx - nx) + (kx <= nx/2) * kx;
    ky = (ky > ny/2) * (ky - ny) + (ky <= ny/2) * ky;
    kz = (kz > nz/2) * (kz - nz) + (kz <= nz/2) * kz;

    array k2 = kx*kx + ky*ky + kz*kz;
    array filter_mask = exp(-k2 / (2.0f * cutoff_freq * cutoff_freq));

    return fft_result * filter_mask;
}

array process_cryo_em_map(const char* filename, int nx, int ny, int nz, float cutoff) {
    info();

    printf("Loading density map from %s\n", filename);
    array density_map = load_density_map(filename, nx, ny, nz);

    printf("Density map shape: %d x %d x %d\n", nx, ny, nz);
    printf("Performing 3D FFT on GPU...\n");

    timer::start();
    array fft_result = fft3(density_map);
    af::sync();
    double fft_time = timer::stop();

    printf("FFT completed in %.3f ms\n", fft_time * 1000.0);
    printf("Applying low-pass filter (cutoff=%.2f)...\n", cutoff);

    timer::start();
    array filtered = apply_filter(fft_result, cutoff);
    af::sync();
    double filter_time = timer::stop();

    printf("Filter applied in %.3f ms\n", filter_time * 1000.0);
    printf("Performing inverse FFT...\n");

    timer::start();
    array result = real(ifft3(filtered));
    af::sync();
    double ifft_time = timer::stop();

    printf("Inverse FFT completed in %.3f ms\n", ifft_time * 1000.0);
    printf("Total processing time: %.3f ms\n", (fft_time + filter_time + ifft_time) * 1000.0);

    return result;
}

int main(int argc, char** argv) {
    try {
        setDevice(0);

        int nx = 256;
        int ny = 256;
        int nz = 256;
        float cutoff = 10.0f;

        if (argc > 1) {
            nx = ny = nz = atoi(argv[1]);
        }
        if (argc > 2) {
            cutoff = atof(argv[2]);
        }

        printf("ArrayFire Cryo-EM Map Processing\n");
        printf("=================================\n");

        array result = process_cryo_em_map("density.mrc", nx, ny, nz, cutoff);

        printf("\nResult statistics:\n");
        printf("  Min: %.6f\n", min<float>(result));
        printf("  Max: %.6f\n", max<float>(result));
        printf("  Mean: %.6f\n", mean<float>(result));
        printf("  Std: %.6f\n", stdev<float>(result));

        return 0;

    } catch (af::exception& e) {
        fprintf(stderr, "ArrayFire exception: %s\n", e.what());
        return 1;
    }
}
```

