## 7. Halide Contact Map

**halide_contact.cpp**

```cpp
#include "Halide.h"
#include <stdio.h>
#include <math.h>

using namespace Halide;

int main(int argc, char **argv) {
    int n_residues = 512;
    if (argc > 1) {
        n_residues = atoi(argv[1]);
    }

    printf("Generating contact map for %d residues\n", n_residues);

    Buffer<float> coords(3, n_residues);
    for (int i = 0; i < n_residues; i++) {
        coords(0, i) = cos(i * 0.1f) * 10.0f;
        coords(1, i) = sin(i * 0.1f) * 10.0f;
        coords(2, i) = i * 0.5f;
    }

    Var x("x"), y("y"), xi("xi"), yi("yi");

    Func contact_map("contact_map");
    Func dist_sq("dist_sq");

    RDom k(0, 3);
    Expr diff = coords(k, x) - coords(k, y);
    dist_sq(x, y) = sum(diff * diff);

    Expr distance = sqrt(dist_sq(x, y));
    contact_map(x, y) = select(distance < 8.0f, 1.0f, 0.0f);

    Var xi_outer, yi_outer;

    if (get_jit_target_from_environment().has_gpu_feature()) {
        contact_map.gpu_tile(x, y, xi, yi, 16, 16);
        printf("Using GPU execution\n");
    } else {
        contact_map.tile(x, y, xi, yi, 16, 16)
                   .parallel(y)
                   .vectorize(xi, 8);
        printf("Using CPU execution\n");
    }

    Buffer<float> output = contact_map.realize({n_residues, n_residues});

    int contact_count = 0;
    for (int i = 0; i < n_residues; i++) {
        for (int j = 0; j < n_residues; j++) {
            if (output(i, j) > 0.5f) {
                contact_count++;
            }
        }
    }

    printf("Total contacts found: %d\n", contact_count);
    printf("Contact density: %.2f%%\n", 100.0f * contact_count / (n_residues * n_residues));

    return 0;
}
