## 8. OpenCL Multi-GPU

**opencl_multi_gpu.py**

```python
import pyopencl as cl
import numpy as np
import time

def create_context_for_all_gpus():
    platforms = cl.get_platforms()
    devices = []
    for platform in platforms:
        gpu_devices = platform.get_devices(device_type=cl.device_type.GPU)
        devices.extend(gpu_devices)

    if not devices:
        raise RuntimeError("No GPU devices found")

    contexts = [cl.Context([device]) for device in devices]
    queues = [cl.CommandQueue(ctx) for ctx in contexts]

    return contexts, queues, devices

def build_inference_kernel():
    kernel_code = """
    __kernel void forward_pass(
        __global const float* input,
        __global const float* weights,
        __global float* output,
        const int n_features,
        const int n_hidden
    ) {
        int idx = get_global_id(0);
        if (idx >= n_hidden) return;

        float sum = 0.0f;
        for (int i = 0; i < n_features; i++) {
            sum += input[i] * weights[idx * n_features + i];
        }
        output[idx] = tanh(sum);
    }
    """
    return kernel_code

def run_multi_gpu_inference(sequences, n_gpus=8):
    contexts, queues, devices = create_context_for_all_gpus()
    n_gpus = min(n_gpus, len(devices))

    print(f"Running inference on {n_gpus} GPUs")
    for i, device in enumerate(devices[:n_gpus]):
        print(f"  GPU {i}: {device.name}")

    kernel_code = build_inference_kernel()
    programs = [cl.Program(ctx, kernel_code).build() for ctx in contexts[:n_gpus]]

    n_features = 1024
    n_hidden = 2048
    batch_size = len(sequences)
    batch_per_gpu = batch_size // n_gpus

    weights = np.random.randn(n_hidden, n_features).astype(np.float32)

    results = []
    start_time = time.time()

    for gpu_id in range(n_gpus):
        start_idx = gpu_id * batch_per_gpu
        end_idx = start_idx + batch_per_gpu if gpu_id < n_gpus - 1 else batch_size

        batch_sequences = sequences[start_idx:end_idx]
        batch_inputs = np.random.randn(len(batch_sequences), n_features).astype(np.float32)

        ctx = contexts[gpu_id]
        queue = queues[gpu_id]
        program = programs[gpu_id]

        mf = cl.mem_flags
        input_buf = cl.Buffer(ctx, mf.READ_ONLY | mf.COPY_HOST_PTR, hostbuf=batch_inputs.flatten())
        weights_buf = cl.Buffer(ctx, mf.READ_ONLY | mf.COPY_HOST_PTR, hostbuf=weights.flatten())
        output_buf = cl.Buffer(ctx, mf.WRITE_ONLY, batch_inputs.shape[0] * n_hidden * 4)

        for seq_idx in range(len(batch_sequences)):
            input_offset = seq_idx * n_features
            output_offset = seq_idx * n_hidden

            program.forward_pass(
                queue,
                (n_hidden,),
                None,
                input_buf,
                weights_buf,
                output_buf,
                np.int32(n_features),
                np.int32(n_hidden)
            )

        output = np.empty(len(batch_sequences) * n_hidden, dtype=np.float32)
        cl.enqueue_copy(queue, output, output_buf).wait()

        results.extend(output.reshape(-1, n_hidden))

    elapsed = time.time() - start_time
    throughput = batch_size / elapsed

    print(f"\nInference complete:")
    print(f"  Total sequences: {batch_size}")
    print(f"  Time: {elapsed:.3f}s")
    print(f"  Throughput: {throughput:.1f} sequences/s")
    print(f"  Per-GPU throughput: {throughput/n_gpus:.1f} sequences/s")

    return np.array(results)

if __name__ == "__main__":
    sequences = ["SEQUENCE" + str(i) for i in range(64)]
    results = run_multi_gpu_inference(sequences, n_gpus=8)
    print(f"\nOutput shape: {results.shape}")
    print(f"Output range: [{results.min():.3f}, {results.max():.3f}]")
