has_binding_site(spike_protein, site_rbm).
has_binding_site(ace2_receptor, site_pd).
has_binding_site(ace2_receptor, site_catalytic).
has_binding_site(p53_protein, site_dna_binding).
has_binding_site(p53_protein, site_tetramerization).
has_binding_site(mdm2_protein, site_p53_binding).
has_binding_site(kinase_abl, site_atp).
has_binding_site(kinase_abl, site_substrate).

compatible_sites(site_rbm, site_pd).
compatible_sites(site_pd, site_rbm).
compatible_sites(site_p53_binding, site_tetramerization).
compatible_sites(site_dna_binding, dna_site).

protein_binds(P1, P2) :-
    has_binding_site(P1, Site1),
    has_binding_site(P2, Site2),
    compatible_sites(Site1, Site2).

druggable(ace2_receptor).
druggable(kinase_abl).
druggable(mdm2_protein).
druggable(p53_protein).

protein_structure(spike_protein, alpha_helix, [10, 50]).
protein_structure(spike_protein, beta_sheet, [100, 150]).
protein_structure(ace2_receptor, alpha_helix, [20, 80]).
protein_structure(p53_protein, beta_sheet, [150, 200]).

interaction_energy(spike_protein, ace2_receptor, -12.5).
interaction_energy(p53_protein, mdm2_protein, -8.3).
interaction_energy(p53_protein, dna, -15.7).

find_drug_targets(Protein, Targets) :-
    findall(X, (protein_binds(Protein, X), druggable(X)), Targets).

calculate_binding_score(P1, P2, Score) :-
    interaction_energy(P1, P2, Energy),
    has_binding_site(P1, S1),
    has_binding_site(P2, S2),
    compatible_sites(S1, S2),
    Score is abs(Energy) * 10.

predict_complex_stability(P1, P2, Stability) :-
    interaction_energy(P1, P2, Energy),
    (   Energy < -10.0
    ->  Stability = high
    ;   Energy < -5.0
    ->  Stability = medium
    ;   Stability = low
    ).

find_interaction_network(Protein, Network) :-
    findall(P, protein_binds(Protein, P), DirectPartners),
    findall(P2, (member(P1, DirectPartners), protein_binds(P1, P2)), IndirectPartners),
    append(DirectPartners, IndirectPartners, AllPartners),
    list_to_set(AllPartners, Network).

query_secondary_structure(Protein, StructureType, Ranges) :-
    findall(Range, protein_structure(Protein, StructureType, Range), Ranges).

strongest_interaction(Protein, Partner, Energy) :-
    findall(E-P, interaction_energy(Protein, P, E), Pairs),
    sort(Pairs, Sorted),
    Sorted = [Energy-Partner|_].

main :-
    writeln('Protein Knowledge Base Query System'),
    writeln('==================================='),
    nl,

    writeln('Query 1: Find drug targets that bind to spike_protein'),
    find_drug_targets(spike_protein, Targets1),
    format('  Result: ~w~n', [Targets1]),
    nl,

    writeln('Query 2: Calculate binding score for p53 and mdm2'),
    calculate_binding_score(p53_protein, mdm2_protein, Score),
