    predict_complex_stability(spike_protein, ace2_receptor, Stability),
    format('  Stability: ~w~n', [Stability]),
    nl,

    writeln('Query 4: Find interaction network for p53'),
    find_interaction_network(p53_protein, Network),
    format('  Network: ~w~n', [Network]),
    nl,

    writeln('Query 5: Query secondary structure of spike_protein'),
    query_secondary_structure(spike_protein, alpha_helix, Helices),
    format('  Alpha helices: ~w~n', [Helices]),
    nl,

    writeln('Query 6: Find strongest interaction for spike_protein'),
    strongest_interaction(spike_protein, Partner, Energy),
    format('  Strongest partner: ~w with energy ~2f kcal/mol~n', [Partner, Energy]),

    halt.
