    :db/doc "Prediction confidence score"}

   {:db/ident :protein/coordinates
    :db/valueType :db.type/string
    :db/cardinality :db.cardinality/one
    :db/doc "3D coordinates as JSON"}

   {:db/ident :protein/plddt
    :db/valueType :db.type/double
    :db/cardinality :db.cardinality/one
    :db/doc "pLDDT score"}])

(defn init-db []
  (d/create-database db-uri)
  (let [conn (d/connect db-uri)]
    @(d/transact conn (create-schema))
    conn))

(defn add-protein [conn protein-data]
  @(d/transact conn
     [{:protein/name (:name protein-data)
       :protein/sequence (:sequence protein-data)
       :protein/confidence (:confidence protein-data)
       :protein/coordinates (:coordinates protein-data)
       :protein/plddt (:plddt protein-data)}]))

(defn add-mutation [conn protein-name mutation]
  (let [db (d/db conn)
        protein-id [:protein/name protein-name]]
    @(d/transact conn
       [[:db/add protein-id :protein/mutation mutation]])))

(defn query-protein-history [conn protein-name]
  (let [db (d/db conn)
        history-db (d/history db)]
    (d/q '[:find ?mutation ?time
           :in $ ?name
           :where
           [?e :protein/name ?name]
           [?e :protein/mutation ?mutation ?tx]
           [?tx :db/txInstant ?time]]
         history-db
         protein-name)))

(defn query-proteins-before-date [conn date]
  (let [db (d/db conn)
        as-of-db (d/as-of db date)]
    (d/q '[:find ?name ?conf
           :where
           [?e :protein/name ?name]
           [?e :protein/confidence ?conf]]
         as-of-db)))

(defn query-high-confidence-proteins [conn threshold]
  (d/q '[:find ?name ?conf ?plddt
         :in $ ?threshold
         :where
         [?e :protein/name ?name]
         [?e :protein/confidence ?conf]
         [?e :protein/plddt ?plddt]
         [(> ?conf ?threshold)]]
       (d/db conn)
       threshold))

(defn query-mutations-in-timerange [conn start-date end-date]
  (let [db (d/db conn)
        history-db (d/history db)]
    (d/q '[:find ?protein ?mutation ?time
           :in $ ?start ?end
           :where
           [?e :protein/name ?protein]
           [?e :protein/mutation ?mutation ?tx]
           [?tx :db/txInstant ?time]
           [(> ?time ?start)]
           [(< ?time ?end)]]
         history-db
         start-date
         end-date)))

