#include "redismodule.h"
#include <string.h>
#include <stdio.h>
#include <stdlib.h>

#define CACHE_KEY_PREFIX "structure:"
#define MAX_COORD_SIZE 1048576

int StructureCache_Set(RedisModuleCtx *ctx, RedisModuleString **argv, int argc) {
    if (argc != 4) {
        return RedisModule_WrongArity(ctx);
    }

    RedisModuleString *sequence = argv[1];
    RedisModuleString *coordinates = argv[2];
    RedisModuleString *confidence = argv[3];

    size_t seq_len;
    const char *seq_str = RedisModule_StringPtrLen(sequence, &seq_len);

    char cache_key[512];
    snprintf(cache_key, sizeof(cache_key), "%s%s", CACHE_KEY_PREFIX, seq_str);

    RedisModuleKey *key = RedisModule_OpenKey(ctx, 
        RedisModule_CreateString(ctx, cache_key, strlen(cache_key)),
        REDISMODULE_WRITE);

    RedisModuleString *value = RedisModule_CreateStringPrintf(ctx,
        "{\"coordinates\":%s,\"confidence\":%s}", 
        RedisModule_StringPtrLen(coordinates, NULL), 
        RedisModule_StringPtrLen(confidence, NULL));

    RedisModule_StringSet(key, value);
    RedisModule_Expire(key, 3600000); // 1 hour expiration

    RedisModule_CloseKey(key);

    RedisModule_ReplyWithSimpleString(ctx, "OK");
    return REDISMODULE_OK;
}

int StructureCache_Get(RedisModuleCtx *ctx, RedisModuleString **argv, int argc) {
    if (argc != 2) {
        return RedisModule_WrongArity(ctx);
    }

    RedisModuleString *sequence = argv[1];
    size_t seq_len;
    const char *seq_str = RedisModule_StringPtrLen(sequence, &seq_len);

    char cache_key[512];
