    RedisModuleKey *key = RedisModule_OpenKey(ctx,
        RedisModule_CreateString(ctx, cache_key, strlen(cache_key)),
        REDISMODULE_READ);

    if (RedisModule_KeyType(key) == REDISMODULE_KEYTYPE_EMPTY) {
        RedisModule_CloseKey(key);
        return RedisModule_ReplyWithNull(ctx);
    }

    size_t value_len;
    char *value_str = RedisModule_StringDMA(key, &value_len, REDISMODULE_READ);

    RedisModule_ReplyWithStringBuffer(ctx, value_str, value_len);
    RedisModule_CloseKey(key);

    return REDISMODULE_OK;
}

int RedisModule_OnLoad(RedisModuleCtx *ctx, RedisModuleString **argv, int argc) {
    if (RedisModule_Init(ctx, "structurecache", 1, REDISMODULE_APIVER_1) == REDISMODULE_ERR) {
        return REDISMODULE_ERR;
