    if (RedisModule_CreateCommand(ctx, "structure.get", StructureCache_Get, "readonly fast", 1, 1, 1) == REDISMODULE_ERR) {
        return REDISMODULE_ERR;
    }

    return REDISMODULE_OK;
}
