## 13. Q# Kvantum Kémia

**VQE.qs**

```qsharp
namespace Quantum.Chemistry.VQE {
    open Microsoft.Quantum.Chemistry;
    open Microsoft.Quantum.Chemistry.JordanWigner;
    open Microsoft.Quantum.Chemistry.OrbitalIntegrals;
    open Microsoft.Quantum.Intrinsic;
    open Microsoft.Quantum.Canon;
    open Microsoft.Quantum.Math;
    open Microsoft.Quantum.Arrays;
    open Microsoft.Quantum.Measurement;

    operation UCC_Ansatz(qubits : Qubit[], trotterStep : Double, parameters : Double[]) : Unit is Adj + Ctl {
        let nQubits = Length(qubits);
        let nSingles = nQubits * (nQubits - 1) / 2;
        let nDoubles = nQubits * (nQubits - 1) * (nQubits - 2) * (nQubits - 3) / 24;

        for i in 0 .. nQubits - 1 {
            H(qubits[i]);
        }

        for idx in 0 .. Length(parameters) - 1 {
            let (p, q, r, s) = GetIndices(idx, nQubits);

            if r == -1 and s == -1 {
                let term = [PauliX, PauliY] w/ [p, q];
                Exp(term, parameters[idx] * trotterStep, qubits);
            } else {
                let term = [PauliX, PauliX, PauliY, PauliY] w/ [p, q, r, s];
                Exp(term, parameters[idx] * trotterStep, qubits);
            }
        }
    }

    function GetIndices(idx : Int, nQubits : Int) : (Int, Int, Int, Int) {
        mutable p = -1; mutable q = -1; mutable r = -1; mutable s = -1;
        // This is a simplified mapping. A real implementation would use a proper
        // indexing scheme for single and double excitations.
        if idx < nQubits {
            set p = idx;
            set q = (idx + 1) % nQubits;
        } else {
            set p = idx % nQubits;
            set q = (idx + 1) % nQubits;
            set r = (idx + 2) % nQubits;
            set s = (idx + 3) % nQubits;
        }
        return (p, q, r, s);
    }

    operation EstimateEnergy(ansatz : (Qubit[], Double, Double[] => Unit), hamiltonian : JordanWignerEncodingData, parameters : Double[]) : Double {
        let nQubits = hamiltonian::NElectrons;
        use qubits = Qubit[nQubits];

        ansatz(qubits, 1.0, parameters);

        let trotterStep = 0.1;
        let trotterOrder = 1;

        let energy = EstimateEnergyWithTrotter(qubits, hamiltonian, trotterStep, trotterOrder);

        ResetAll(qubits);
        return energy;
    }

    operation EstimateEnergyWithTrotter(qubits: Qubit[], data: JordanWignerEncodingData, trotterStepSize: Double, trotterOrder: Int) : Double {
        let (nTerms, terms) = data::Terms;
        mutable totalEnergy = 0.0;

        for i in 0 .. nTerms - 1 {
            let (coeffs, paulis) = terms[i];
            let (pauliString, pauliTargets) = ToPauliTuple(paulis, qubits);

            if Length(pauliString) > 0 {
                let expectation = EstimatePauliStringExpectation(pauliString, pauliTargets);
                set totalEnergy = totalEnergy + coeffs[0] * expectation;
            }
        }
        return totalEnergy;
    }

    function ToPauliTuple(paulis : Int[], qubits: Qubit[]) : (Pauli[], Qubit[]) {
        let nPaulis = Length(paulis) / 2;
        mutable pauliString = new Pauli[nPaulis];
        mutable pauliTargets = new Qubit[nPaulis];

        for i in 0 .. nPaulis - 1 {
            let targetQubit = paulis[2 * i];
            let pauli = paulis[2 * i + 1];
            set pauliTargets w/= i <- qubits[targetQubit];
            set pauliString w/= i <- pauli == 1 ? PauliX | (pauli == 2 ? PauliY | PauliZ);
        }
        return (pauliString, pauliTargets);
    }

    operation VQE_GroundState(hamiltonian : JordanWignerEncodingData) : (Double, Double[]) {
        let nParameters = 10; 
        mutable parameters = new Double[nParameters];

        // This would be replaced by a classical optimizer loop (e.g., SPSA, L-BFGS)
        for iter in 1..10 {
            let energy = EstimateEnergy(UCC_Ansatz, hamiltonian, parameters);
            let gradients = CalculateGradients(hamiltonian, parameters);

            for i in 0..nParameters-1 {
                set parameters w/= i <- parameters[i] - 0.1 * gradients[i];
            }
        }

        let finalEnergy = EstimateEnergy(UCC_Ansatz, hamiltonian, parameters);
        return (finalEnergy, parameters);
    }

    function CalculateGradients(hamiltonian : JordanWignerEncodingData, parameters : Double[]) : Double[] {
        let nParams = Length(parameters);
        mutable gradients = new Double[nParams];
        let shift = PI() / 2.0;

        for i in 0..nParams-1 {
            let shifted_plus = parameters w/ i <- parameters[i] + shift;
            let shifted_minus = parameters w/ i <- parameters[i] - shift;

            let energy_plus = EstimateEnergy(UCC_Ansatz, hamiltonian, shifted_plus);
            let energy_minus = EstimateEnergy(UCC_Ansatz, hamiltonian, shifted_minus);

            set gradients w/= i <- (energy_plus - energy_minus) / 2.0;
        }
        return gradients;
    }
}
