**phase_estimation.slq**

```silq
import std;

def controlled_power(U: const qfunc(q:qubit):qubit, power: uint, c: qubit, t: qubit) -> (qubit, qubit) {
  if c {
    loop i in 0..power-1 {
      t := U(t);
    }
  }
  return (c, t);
}

def quantum_phase_estimation(U: const qfunc(q:qubit):qubit, t: qubit, n: uint) -> uint[n] {
  phase_reg := H(0:^n);

  loop i in 0..n-1 {
    let power = 2^(n-1-i);
    (phase_reg[i], t) := controlled_power(U, power, phase_reg[i], t);
  }

  phase_reg := QFT_inverse(phase_reg);
  return measure(phase_reg);
}

def main() {
  // Example: U = T-gate, eigenvector |1>
  // T|1> = exp(i*pi/4)|1>, so phase is 1/8 = 0.125
  // Binary 0.001
  let U = T;
  let eigenvector = X(0:qubit);

  let num_estimation_qubits = 4;
  let phase_estimate = quantum_phase_estimation(U, eigenvector, num_estimation_qubits);

  // Expected output for 4 qubits: 2 (binary 0010), representing 2/16 = 0.125
  print(phase_estimate);
}
