## 15. Qiskit IBM Backend

**submit_ibm_job.py**

```python
import os
from qiskit import QuantumCircuit, transpile
from qiskit_ibm_provider import IBMProvider

def get_ibm_provider():
    api_token = os.environ.get("IBM_QUANTUM_TOKEN")
    if not api_token:
        raise ValueError("IBM_QUANTUM_TOKEN environment variable not set.")

    try:
        provider = IBMProvider()
        return provider
    except Exception as e:
        print(f"Failed to instantiate IBMProvider: {e}")
        return None

def create_ghz_circuit(num_qubits):
    qc = QuantumCircuit(num_qubits, num_qubits)
    qc.h(0)
    for i in range(num_qubits - 1):
        qc.cx(i, i + 1)
    qc.measure(range(num_qubits), range(num_qubits))
    return qc

def submit_to_ibm_quantum(num_qubits=127, shots=8192):
    provider = get_ibm_provider()
    if not provider:
        print("Could not connect to IBM Quantum. Exiting.")
        return

    try:
        backend = provider.get_backend('ibm_nazca')
        print(f"Successfully connected to backend: {backend.name}")
        print(f"  Version: {backend.backend_version}, Qubits: {backend.num_qubits}")
    except Exception as e:
        print(f"Could not get backend 'ibm_nazca'. Error: {e}")
        print("Attempting to find another backend with at least 127 qubits.")
        available_backends = provider.backends(
            filters=lambda b: b.num_qubits >= num_qubits and not b.simulator
        )
        if not available_backends:
            print("No suitable backend found. Exiting.")
            return
        backend = available_backends[0]
        print(f"Using fallback backend: {backend.name}")

    if backend.num_qubits < num_qubits:
        print(f"Selected backend has only {backend.num_qubits} qubits. Reducing circuit size.")
        num_qubits = backend.num_qubits

    print(f"\nCreating a {num_qubits}-qubit GHZ state circuit...")
    circuit = create_ghz_circuit(num_qubits)

    print("Transpiling circuit for the target backend...")
    transpiled_circuit = transpile(circuit, backend=backend, optimization_level=3)

    print(f"Submitting job with {shots} shots to {backend.name}...")
    try:
        job = backend.run(transpiled_circuit, shots=shots, dynamic=False)
        print(f"Job submitted successfully. Job ID: {job.job_id()}")

        print("Waiting for job to complete... (This may take several minutes to hours)")
        result = job.result()

        print("\nJob completed!")
        counts = result.get_counts(transpiled_circuit)

        print("\nResults:")
        print(f"  Execution time: {result.time_taken:.2f} seconds")

        all_zeros = '0' * num_qubits
        all_ones = '1' * num_qubits

        print(f"  Counts for '{all_zeros}': {counts.get(all_zeros, 0)}")
        print(f"  Counts for '{all_ones}': {counts.get(all_ones, 0)}")

        other_counts = sum(v for k, v in counts.items() if k not in [all_zeros, all_ones])
        print(f"  Counts for other states (errors): {other_counts}")

    except Exception as e:
        print(f"An error occurred during job submission or execution: {e}")

if __name__ == "__main__":
    submit_to_ibm_quantum()
