## 16. JAX Gradiens

**jax_training.py**

```python
import jax
import jax.numpy as jnp
from jax import random
import optax
import time

def init_network_params(sizes, key):
    keys = random.split(key, len(sizes))

    def init_layer(m, n, k, scale=1e-2):
        w_key, b_key = random.split(k)
        return scale * random.normal(w_key, (n, m)), scale * random.normal(b_key, (m,))

    return [init_layer(m, n, k) for m, n, k in zip(sizes[1:], sizes[:-1], keys)]

@jax.jit
def predict(params, inputs):
    activations = inputs
    for w, b in params[:-1]:
        outputs = jnp.dot(activations, w.T) + b
        activations = jax.nn.relu(outputs)

    final_w, final_b = params[-1]
    logits = jnp.dot(activations, final_w.T) + final_b
    return logits

@jax.jit
def loss_function(params, inputs, targets):
    preds = predict(params, inputs)
    return jnp.mean((preds - targets) ** 2)

@jax.jit
def update_step(params, opt_state, inputs, targets, optimizer):
    loss, grads = jax.value_and_grad(loss_function)(params, inputs, targets)
    updates, opt_state = optimizer.update(grads, opt_state)
    new_params = optax.apply_updates(params, updates)
    return new_params, opt_state, loss

def train_model(epochs=100, batch_size=128, learning_rate=1e-3):
    layer_sizes = [784, 1024, 1024, 10]
    key = random.PRNGKey(0)

    params = init_network_params(layer_sizes, key)

    optimizer = optax.adam(learning_rate)
    opt_state = optimizer.init(params)

    num_samples = 50000
    input_shape = (num_samples, 784)
    target_shape = (num_samples, 10)

    train_key, test_key = random.split(key)
    train_images = random.normal(train_key, input_shape)
    train_labels = random.normal(train_key, target_shape)

    num_batches = num_samples // batch_size

    print("Starting JAX training with XLA compilation...")
    start_time = time.time()

    for epoch in range(epochs):
        epoch_loss = 0.0
        perm_key, key = random.split(key)
        permutation = random.permutation(perm_key, num_samples)

        for i in range(num_batches):
            batch_idx = permutation[i * batch_size : (i + 1) * batch_size]
            batch_inputs = train_images[batch_idx]
            batch_targets = train_labels[batch_idx]

            params, opt_state, loss = update_step(params, opt_state, batch_inputs, batch_targets, optimizer)
            epoch_loss += loss

        avg_loss = epoch_loss / num_batches
        if (epoch + 1) % 10 == 0:
            print(f"Epoch {epoch+1:3d}/{epochs} | Average Loss: {avg_loss:.6f}")

    end_time = time.time()
    print(f"\nTraining finished in {end_time - start_time:.2f} seconds.")

    test_images = random.normal(test_key, (10000, 784))
    test_labels = random.normal(test_key, (10000, 10))
    test_loss = loss_function(params, test_images, test_labels)
    print(f"Final test loss: {test_loss:.6f}")

if __name__ == "__main__":
    train_model()
```

