## 17. MLX Apple Silicon

**mlx_inference.py**

```python
import mlx.core as mx
import mlx.nn as nn
import mlx.optimizers as optim
import time
import numpy as np

class TransformerBlock(nn.Module):
    def __init__(self, dim: int, num_heads: int, mlp_dim: int):
        super().__init__()
        self.attention = nn.MultiHeadAttention(dim, num_heads)
        self.ln1 = nn.LayerNorm(dim)
        self.ln2 = nn.LayerNorm(dim)
        self.mlp = nn.Sequential(
            nn.Linear(dim, mlp_dim),
            nn.GELU(),
            nn.Linear(mlp_dim, dim)
        )

    def __call__(self, x):
        attn_output = self.attention(x, x, x)
        x = self.ln1(x + attn_output)
        mlp_output = self.mlp(x)
        x = self.ln2(x + mlp_output)
        return x

def run_inference_benchmark(batch_size=32, seq_len=512, dim=768, num_heads=12, mlp_dim=3072, num_layers=6):
    print(f"Running MLX inference on Apple Silicon (M-series GPU / Neural Engine)")
    print(f"Batch size: {batch_size}, Sequence length: {seq_len}, Dim: {dim}")

    model = nn.Sequential(*[TransformerBlock(dim, num_heads, mlp_dim) for _ in range(num_layers)])

    # Ensure model parameters are on the device
    mx.eval(model.parameters())

    # Create dummy input data
    input_data = mx.random.uniform(shape=(batch_size, seq_len, dim))

    # Eager evaluation for the first run to compile kernels
    print("Performing warmup run...")
    _ = model(input_data)
    mx.eval()

    print("Starting benchmark...")
    num_runs = 50
    start_time = time.time()

    for _ in range(num_runs):
        output = model(input_data)
        mx.eval(output) # Synchronize to ensure computation is complete

    end_time = time.time()

    total_time = end_time - start_time
    avg_latency_ms = (total_time / num_runs) * 1000
    throughput = num_runs * batch_size / total_time

    print("\n--- Benchmark Results ---")
    print(f"Total time for {num_runs} runs: {total_time:.3f} s")
    print(f"Average latency per batch: {avg_latency_ms:.2f} ms")
    print(f"Throughput: {throughput:.2f} sequences/s")

    # Verify output shape
    output_shape = model(input_data).shape
    print(f"\nOutput shape: {output_shape}")
    if output_shape == (batch_size, seq_len, dim):
        print("Output shape is correct.")
    else:
        print("Error: Output shape mismatch!")

if __name__ == "__main__":
    run_inference_benchmark()
