import onnxruntime as ort
import numpy as np
import time
import torch
import torch.nn as nn

class SimpleModel(nn.Module):
    def __init__(self):
        super(SimpleModel, self).__init__()
        self.layer1 = nn.Linear(1024, 2048)
        self.relu = nn.ReLU()
        self.layer2 = nn.Linear(2048, 512)
        self.dropout = nn.Dropout(0.2)
        self.output = nn.Linear(512, 10)

    def forward(self, x):
        x = self.relu(self.layer1(x))
        x = self.relu(self.layer2(x))
        x = self.dropout(x)
        return self.output(x)

def export_to_onnx(model, onnx_path="model.onnx"):
    dummy_input = torch.randn(1, 1024, requires_grad=True)
    torch.onnx.export(
        model,
        dummy_input,
        onnx_path,
        export_params=True,
        opset_version=14,
        do_constant_folding=True,
        input_names=['input'],
        output_names=['output'],
        dynamic_axes={'input': {0: 'batch_size'}, 'output': {0: 'batch_size'}}
    )
    print(f"Model exported to {onnx_path}")

def run_onnx_inference(onnx_path="model.onnx", batch_size=64):
    print("\n--- ONNX Runtime Inference ---")

    available_providers = ort.get_available_providers()
    print(f"Available execution providers: {available_providers}")

    providers = [
        ('CUDAExecutionProvider', {'device_id': 0}),
        'CPUExecutionProvider'
    ]

    try:
        session = ort.InferenceSession(onnx_path, providers=providers)
        selected_provider = session.get_providers()[0]
        print(f"Using provider: {selected_provider}")
    except Exception as e:
        print(f"Could not create session with preferred providers. Error: {e}")
        return

    input_name = session.get_inputs()[0].name
    output_name = session.get_outputs()[0].name

    input_shape = (batch_size, 1024)
    input_data = np.random.randn(*input_shape).astype(np.float32)

    print("Performing warmup run...")
    session.run([output_name], {input_name: input_data})

    print("Starting benchmark...")
    num_runs = 100
    start_time = time.time()

    for _ in range(num_runs):
        prediction = session.run([output_name], {input_name: input_data})

    end_time = time.time()

    total_time = end_time - start_time
    avg_latency_ms = (total_time / num_runs) * 1000
    throughput = num_runs * batch_size / total_time

    print("\n--- Benchmark Results ---")
    print(f"Total time for {num_runs} runs: {total_time:.3f} s")
    print(f"Average latency per batch: {avg_latency_ms:.2f} ms")
    print(f"Throughput: {throughput:.2f} inferences/s")

    # Verify output
    final_prediction = prediction[0]
    print(f"\nOutput shape: {final_prediction.shape}")
    print(f"Output sample: {final_prediction[0, :5]}")

if __name__ == "__main__":
    model = SimpleModel()
    export_to_onnx(model)
    run_onnx_inference()
