}

fn call_julia_feature_prep(msa_data: String) -> Result(String, PredictionError) {
  // Mocking external service call
  Ok("FEATURES_FROM_" <> msa_data)
}

fn call_futhark_inference(features: String) -> Result(String, PredictionError) {
  // Mocking external service call
  Ok("{\"coordinates\": [[1.0, 2.0], [3.0, 4.0]], \"confidence\": 0.95}")
}

pub fn coordinate_prediction(sequence: String) -> Result(Structure, PredictionError) {
  use msa <- result.try(call_chapel_msa_service(sequence))
  use features <- result.try(call_julia_feature_prep(msa))
  use inference_json <- result.try(call_futhark_inference(features))

  let decoded = json.decode(
    inference_json,
    from: structure_decoder(),
  )

  case decoded {
    Ok(structure) -> Ok(structure)
    Error(e) -> Error(JsonDecodeError(e))
  }
}

fn structure_decoder() -> json.Decoder(Structure) {
  let to_structure = fn(coords, conf) { Structure(coords, conf) }
  json.map2(
    to: to_structure,
    json.field("coordinates", json.list(json.list(json.float))),
    json.field("confidence", json.float),
  )
}

fn handle_request(req: request.Request(Dynamic)) -> response.Response(String) {
  case request.get_path(req) {
    "/predict" -> {
      let body = request.get_body(req)
      let sequence_result = 
        json.decode(body, from: json.field("sequence", json.string))

      case sequence_result {
        Ok(sequence) -> {
          case coordinate_prediction(sequence) {
            Ok(structure) ->
              response.new(200)
              |> response.set_header("content-type", "application/json")
              |> response.set_body(
                json.object([
                  #("coordinates", json.list(structure.coordinates, fn(c) { json.list(c, json.float) })),
                  #("confidence", json.float(structure.confidence)),
                ]) |> json.to_string
              )

            Error(_) -> 
              response.new(500)
              |> response.set_body("Prediction failed")
          }
        }
        Error(_) ->
          response.new(400)
          |> response.set_body("Invalid request body")
      }
    }
    _ -> response.new(404) |> response.set_body("Not Found")
  }
}

pub fn main() {
  let service = service.fn_service(handle_request)
  let assert Ok(_) = elli.start(service, on_port: 8000)
  process.sleep_forever()
}
